<?php
 namespace Pterodactyl\Services\Dezerx; use Throwable; use Carbon\CarbonImmutable; use Illuminate\Support\Str; use Pterodactyl\Models\User; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Cache; use Pterodactyl\Models\Dezerx\RecycledFile; use Pterodactyl\Repositories\Wings\DaemonFileRepository; class RecycleBin { public const LEGACY_DIRECTORY = '/.dezerx-recycle-bin'; public const DEFAULT_RETENTION_DAYS = 7; public function __construct(private readonly DaemonFileRepository $repository) { } public static function appliesTo(Server $server): bool { return Addons::appliesTo(Addons::RECYCLE_BIN, $server); } public static function retentionDays(): int { $configured = (int) (Addons::get(Addons::RECYCLE_BIN)['retention_days'] ?? 0); return $configured > 0 ? min($configured, 365) : self::DEFAULT_RETENTION_DAYS; } public static function directory(): string { return '/' . Brand::file('recycle-bin'); } public static function directories(): array { return array_map(fn (string $name) => '/' . $name, Brand::files('recycle-bin')); } public static function holds(string $root): bool { $root = '/' . trim($root, '/'); foreach (self::directories() as $directory) { if ($root === $directory || str_starts_with($root . '/', $directory . '/')) { return true; } } return false; } public function trash(Server $server, ?User $user, string $root, array $names): array { if (self::holds($root)) { RecycledFile::query()->where('server_id', $server->id)->whereIn('stored_name', $names)->delete(); return $names; } $this->repository->setServer($server); $this->adopt($server); $this->ensureDirectory($server); $directory = self::directory(); $existing = collect($this->listing($server, $root))->keyBy('name'); $now = CarbonImmutable::now(); $expires = $now->addDays(self::retentionDays()); $failed = []; foreach ($names as $name) { $entry = $existing->get($name); if ($entry === null || self::holds($this->join($root, $name))) { $failed[] = $name; continue; } $stored = $this->uniqueName($server, $name); try { $this->repository->renameFiles(null, [['from' => $this->join($root, $name), 'to' => $directory . '/' . $stored]]); } catch (Throwable) { $failed[] = $name; continue; } RecycledFile::query()->create([ 'server_id' => $server->id, 'user_id' => $user?->id, 'root' => $root === '' ? '/' : $root, 'name' => $name, 'is_directory' => !(bool) ($entry['file'] ?? true), 'size' => (int) ($entry['size'] ?? 0), 'stored_name' => $stored, 'directory' => $directory, 'deleted_at' => $now, 'expires_at' => $expires, ]); } return $failed; } public function restore(Server $server, RecycledFile $item): string { $this->repository->setServer($server); $destination = $this->freePath($server, $item->root, $item->name); $this->repository->renameFiles(null, [['from' => $this->locate($item) . '/' . $item->stored_name, 'to' => $destination]]); $item->delete(); return $destination; } public function purge(Server $server, RecycledFile $item): void { $this->repository->setServer($server); try { $this->repository->deleteFiles($this->locate($item), [$item->stored_name]); } catch (Throwable) { } $item->delete(); } public function contents(Server $server) { $this->adopt($server); return RecycledFile::query()->where('server_id', $server->id)->orderByDesc('deleted_at')->get(); } private function locate(RecycledFile $item): string { return $item->directory ?: self::LEGACY_DIRECTORY; } private function adopt(Server $server): void { $current = self::directory(); $key = "recycle-bin:adopted:{$server->uuid}:" . md5($current); if (Cache::has($key)) { return; } $names = fn (string $path) => array_column($this->repository->getDirectory($path), 'name'); try { $this->repository->setServer($server); foreach (array_slice(self::directories(), 1) as $old) { $present = $names('/'); $items = fn () => RecycledFile::query() ->where('server_id', $server->id) ->where(fn ($query) => $query->where('directory', $old)->when( $old === self::LEGACY_DIRECTORY, fn ($query) => $query->orWhereNull('directory'), )); if (in_array(ltrim($old, '/'), $present, true) && !in_array(ltrim($current, '/'), $present, true)) { $this->repository->renameFiles(null, [['from' => $old, 'to' => $current]]); $present = $names('/'); } $hasOld = in_array(ltrim($old, '/'), $present, true); $hasCurrent = in_array(ltrim($current, '/'), $present, true); if (!$hasOld && $hasCurrent) { $items()->update(['directory' => $current]); } elseif ($hasOld && $hasCurrent && !$items()->exists() && $names($old) === []) { $this->repository->deleteFiles('/', [ltrim($old, '/')]); } } } catch (Throwable) { return; } Cache::put($key, true, 86400); } private function ensureDirectory(Server $server): void { try { $this->repository->createDirectory(ltrim(self::directory(), '/'), '/'); } catch (Throwable) { } } private function uniqueName(Server $server, string $name): string { $taken = RecycledFile::query()->where('server_id', $server->id)->pluck('stored_name')->flip(); do { $candidate = Str::random(8) . '-' . $name; } while ($taken->has($candidate)); return $candidate; } private function freePath(Server $server, string $root, string $name): string { $taken = collect($this->listing($server, $root))->pluck('name')->flip(); if (!$taken->has($name)) { return $this->join($root, $name); } $dot = strrpos($name, '.'); $stem = $dot === false || $dot === 0 ? $name : substr($name, 0, $dot); $extension = $dot === false || $dot === 0 ? '' : substr($name, $dot); $attempt = 1; do { $candidate = $stem . ' (restored' . ($attempt > 1 ? " {$attempt}" : '') . ')' . $extension; $attempt++; } while ($taken->has($candidate)); return $this->join($root, $candidate); } private function listing(Server $server, string $root): array { try { return $this->repository->setServer($server)->getDirectory($root === '' ? '/' : $root); } catch (Throwable) { return []; } } private function join(string $root, string $name): string { return '/' . trim(rtrim($root, '/') . '/' . $name, '/'); } } 